/**
 * Error type exposed through the `UniFFI` wallet client bindings.
 */
sealed class WcUniFfiException: kotlin.Exception() {
    
    /**
     * A caller-supplied value was invalid.
     */
    class InvalidInput(
        
        /**
         * Human-readable diagnostic.
         */
        val `details`: kotlin.String
        ) : WcUniFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    /**
     * The client is not connected or has already been shut down.
     */
    class State(
        
        /**
         * Human-readable diagnostic.
         */
        val `details`: kotlin.String
        ) : WcUniFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    /**
     * A protocol, relay, or wallet policy operation failed.
     */
    class Operation(
        
        /**
         * Human-readable diagnostic.
         */
        val `details`: kotlin.String
        ) : WcUniFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WcUniFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): WcUniFfiException = FfiConverterTypeWcUniFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeWcUniFfiError : FfiConverterRustBuffer<WcUniFfiException> {
    override fun read(buf: ByteBuffer): WcUniFfiException {
        

        return when(buf.getInt()) {
            1 -> WcUniFfiException.InvalidInput(
                FfiConverterString.read(buf),
                )
            2 -> WcUniFfiException.State(
                FfiConverterString.read(buf),
                )
            3 -> WcUniFfiException.Operation(
